function cleanProgram(p){if(!p||!Array.isArray(p.nodes)||!Array.isArray(p.edges)||p.nodes.length>2000||p.edges.length>15000)throw new Error('프로젝트는 최대 2,000 노드 / 15,000 연결입니다.');const shape=[...functionShapeErrors(p),...variableShapeErrors(p)];if(shape.length)throw new Error(shape.join('\n'));const ids=new Set;for(const n of p.nodes){if(!n||typeof n.id!=='string'||!(/^[A-Za-z0-9_-]{1,100}$/).test(n.id)||ids.has(n.id)||!['api','data','entry','callback','branch','return','write','read','process','handler','runTimer','userEvent','enum','define','for','while','break','continue','calculate','compare','userCall','functionEntry','functionReturn',...VARIABLE_KINDS].includes(n.kind))throw new Error('잘못된 노드 형식');ids.add(n.id);if(graphOf(n)!=='main'&&!functionById(p,graphOf(n)))throw new Error('소속 함수 그래프가 없습니다.');if(!Number.isFinite(n.x)||!Number.isFinite(n.y)||Math.abs(n.x)>30000||Math.abs(n.y)>30000)throw new Error('잘못된 노드 위치');if(n.kind==='api'&&n.api==='DbgPrint')printArguments(n);if(n.kind==='api'&&!exported.get(n.api)?.callable)throw new Error('함수 EXPORT가 아닙니다: '+n.api);if(loopErrors(n).length)throw new Error(loopErrors(n).join('\n'));if(n.kind==='branch'&&branchErrors(n).length)throw new Error(branchErrors(n).join('\n'));if(n.kind==='data'&&!TYPES[n.type])throw new Error('자료형을 찾을 수 없습니다: '+n.type);if(JSON.stringify(n).length>16000)throw new Error('노드 데이터가 너무 큽니다.');}const definitionErrors=validateDefinitions(p,CONSTANTS,literal);if(definitionErrors.length)throw new Error(definitionErrors.join('\n'));for(const e of p.edges){if(!e||!ids.has(e.from)||!ids.has(e.to)||!['data','exec'].includes(e.kind)||typeof e.id!=='string')throw new Error('잘못된 연결');if(graphOf(p.nodes.find(n=>n.id===e.from))!==graphOf(p.nodes.find(n=>n.id===e.to)))throw new Error('함수 그래프 사이에는 인자/반환 핀을 사용하세요.')}return p;}
