function wireFunctionInspector(){wireFunctionLinks($('inspectorBody'));const create=$('createFunctionInspector');if(create)create.onclick=makeUserFunction;const f=selectedFunction();if(!f||inspector!=='function')return;const change=fn=>{let removed=0;commit(()=>{fn();removed=reconcileSignature(program,f,enginePorts,compatible)});if(removed)toast(removed+'개 호환되지 않는 데이터 연결을 제거했습니다.')};$('definitionSelect').onchange=e=>{definitionSelection=e.target.value;renderInspector()};$('applyFunctionName').onclick=()=>{const name=$('functionName').value.trim();if(!/^[A-Za-z_][A-Za-z0-9_]{0,79}$/.test(name)||(program.functions||[]).some(x=>x!==f&&x.name===name)){toast('중복되지 않는 C 식별자(최대 80자)를 입력하세요.');return}change(()=>f.name=name)};$('functionReturnType').onchange=e=>change(()=>f.returnType=e.target.value);$('addFunctionArgument').onclick=()=>change(()=>addParameter(f));document.querySelectorAll('[data-remove-fnarg]').forEach(b=>b.onclick=()=>change(()=>f.args=f.args.filter(a=>a.id!==b.dataset.removeFnarg)));document.querySelectorAll('[data-fnarg-name]').forEach(el=>el.oninput=()=>{const a=f.args.find(a=>a.id===el.dataset.fnargName),name=el.value.trim();if(!/^[A-Za-z_][A-Za-z0-9_]{0,79}$/.test(name)||f.args.some(x=>x!==a&&x.name===name)){toast('중복되지 않는 인자 이름을 입력하세요.');el.value=a.name;return}edit(()=>a.name=name)});document.querySelectorAll('[data-fnarg-type]').forEach(el=>el.onchange=()=>change(()=>f.args.find(a=>a.id===el.dataset.fnargType).type=el.value));document.querySelectorAll('[data-fnarg-default]').forEach(el=>el.oninput=()=>edit(()=>f.args.find(a=>a.id===el.dataset.fnargDefault).default=el.value));$('editFunctionGraph').onclick=()=>{switchGraph(f.id);setInspector('node');requestAnimationFrame(fit)};$('deleteFunctionDefinition').onclick=()=>{commit(()=>{removeFunction(program,f.id);definitionSelection=null;if(graphView===f.id)graphView='main';selected=null});toast('함수와 호출 노드를 삭제했습니다. 실행 취소로 복구할 수 있습니다.')};}
function makeVariable(scope,container='scalar'){if(program.nodes.length>=2000||graphNodes().length>=200){toast('노드 한도에 도달했습니다.');return}try{let n;commit(()=>{const v=createVariable(program,scope,graphView,container);n=newNode('variable',{variableId:v.id,...(graphView==='main'?{}:{graph:graphView}),x:60,y:120});while(graphNodes().some(x=>Math.abs(x.x-n.x)<25&&Math.abs(x.y-n.y)<25)){n.x+=34;n.y+=44}program.nodes.push(n);selected=n.id});setInspector('node');focusNode(n.id,true);toast((scope==='global'?'전역':'지역')+'변수를 만들었습니다.')}catch(e){toast(e.message)}}
function variableNodeLive(n){const v=variableById(program,n?.variableId),r=n&&engine?.variables.describe(n,graphView);return r?esc(r.label)+' · '+esc(aggregateSummary(r.value))+' <small>'+esc(r.container==='scalar'?fmt(r.value):r.cells.length+' cells')+' / '+esc(r.phase)+'</small>':esc((v?.scope==='global'?'GLOBAL':'LOCAL')+' · '+(v?.type||'')+' · 초기값 '+aggregateSummary(v?.initial??'0'));}
function wireVariableInspector(n){if(inspector!=='node')return;const changed=fn=>{let removed=0;commit(()=>{fn();removed=reconcileVariablePins(program,enginePorts,compatible)});if(removed)toast(removed+'개 호환되지 않는 연결을 제거했습니다.')};if(n.kind!=='variable'){if($('variableOperationType'))$('variableOperationType').onchange=e=>changed(()=>n.valueType=e.target.value);if($('accessStructure'))$('accessStructure').onchange=e=>changed(()=>{n.structureId=e.target.value;n.params.Field='0';n.valueType=variableById(program,n.structureId)?.fields?.[0]?.type||'LARGE_INTEGER'});if($('accessField'))$('accessField').onchange=e=>changed(()=>{n.params.Field=e.target.value;n.valueType=variableById(program,n.structureId)?.fields?.[Number(e.target.value)]?.type||'LARGE_INTEGER'});return}const v=variableById(program,n.variableId);if(!v)return;$('variableReference').onchange=e=>changed(()=>n.variableId=e.target.value);$('applyVariableName').onclick=()=>{const name=$('variableName').value.trim();if(!/^[A-Za-z_][A-Za-z0-9_]{0,79}$/.test(name)||(program.variables||[]).some(x=>x!==v&&x.name===name&&x.scope===v.scope&&(v.scope==='global'||x.graph===v.graph))){toast('같은 범위에서 중복되지 않는 C 식별자를 입력하세요.');return}changed(()=>v.name=name)};$('variableType').onchange=e=>changed(()=>{const previous=TYPES[v.type],next=TYPES[e.target.value];v.type=e.target.value;if(next.string&&!previous.string)v.initial='';else if(!next.string&&previous.string)v.initial='0';if(next.opaque)v.initial='0';});$('variableInitial').oninput=e=>edit(()=>v.initial=e.target.value);if($('applyVariableCapacity'))$('applyVariableCapacity').onclick=()=>{try{const capacity=Number($('variableCapacity').value);valueLayout(v.type,v.initial,TYPES,{...v,capacity});changed(()=>v.capacity=capacity)}catch(error){toast(error.message)}};if($('applyVariableCustom'))$('applyVariableCustom').onclick=()=>{try{const customSize=Number($('variableCustomSize').value),customFields=JSON.parse($('variableCustomFields').value);valueLayout(v.type,v.initial,TYPES,{...v,customSize,customFields});changed(()=>{v.customSize=customSize;v.customFields=customFields})}catch(error){toast(error.message)}};$('variableContainer').onchange=e=>changed(()=>{v.container=e.target.value;if(v.container==='array'){v.length??=4;v.values??=[];}if(v.container==='struct'){v.pack??=8;if(!v.fields?.length)addStructField(v);}});if($('applyArrayLength'))$('applyArrayLength').onclick=()=>{const length=Number($('arrayLength').value);if(!Number.isInteger(length)||length<1||length>4096){toast('배열 길이는 1–4096입니다.');return}changed(()=>{v.length=length;if(v.values)v.values=v.values.slice(0,length)})};if($('applyArrayInitialValues'))$('applyArrayInitialValues').onclick=()=>{try{const values=JSON.parse($('arrayInitialValues').value);if(!Array.isArray(values)||values.length>v.length||values.some(x=>{validateInitial(v.type,x,TYPES,resolve,v);return JSON.stringify(x).length>65536}))throw Error('배열 길이 이하의 타입별 초기값 JSON 목록을 입력하세요.');changed(()=>v.values=values)}catch(e){toast(e.message)}};if($('structurePack'))$('structurePack').onchange=e=>changed(()=>v.pack=Number(e.target.value));if($('addAggregateField'))$('addAggregateField').onclick=()=>changed(()=>addStructField(v));document.querySelectorAll('[data-remove-aggregate-field]').forEach(el=>el.onclick=()=>{if(v.fields.length<=1){toast('구조체에는 필드가 한 개 이상 필요합니다.');return}changed(()=>v.fields.splice(Number(el.dataset.removeAggregateField),1))});document.querySelectorAll('[data-aggregate-name]').forEach(el=>el.oninput=()=>{const i=Number(el.dataset.aggregateName),name=el.value.trim();if(!/^[A-Za-z_][A-Za-z0-9_]{0,79}$/.test(name)||v.fields.some((f,j)=>i!==j&&f.name===name)){toast('중복되지 않는 필드 이름을 입력하세요.');el.value=v.fields[i].name;return}edit(()=>v.fields[i].name=name);if($('aggregateLayoutLive'))$('aggregateLayoutLive').innerHTML=layoutPreview(v,TYPES)});document.querySelectorAll('[data-aggregate-type]').forEach(el=>el.onchange=()=>changed(()=>{const f=v.fields[Number(el.dataset.aggregateType)],prev=TYPES[f.type],next=TYPES[el.value];f.type=el.value;if(next.string&&!prev.string)f.initial='';else if(!next.string&&prev.string)f.initial='0';if(next.opaque)f.initial='0';}));document.querySelectorAll('[data-aggregate-capacity]').forEach(el=>el.onchange=()=>{try{const f=v.fields[Number(el.dataset.aggregateCapacity)],capacity=Number(el.value);valueLayout(f.type,f.initial,TYPES,{...f,capacity});changed(()=>f.capacity=capacity)}catch(error){toast(error.message)}});document.querySelectorAll('[data-aggregate-initial]').forEach(el=>el.oninput=()=>edit(()=>v.fields[Number(el.dataset.aggregateInitial)].initial=el.value));$('deleteVariableDefinition').onclick=()=>{commit(()=>{removeVariable(program,v.id);selected=null});toast('변수 정의와 모든 참조를 삭제했습니다. 실행 취소로 복구할 수 있습니다.')};}
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,6500)}
function setInspector(tab){inspector=tab;document.querySelectorAll('[data-inspect]').forEach(b=>b.classList.toggle('active',b.dataset.inspect===tab));document.querySelector('.inspector').classList.add('open');renderInspector()}
function addNode(kind,extra={},point=null){if(internalView?.active){toast('커널 내부 그래프는 읽기 전용입니다.');return;}if(graphNodes().length>=200||program.nodes.length>=2000){toast('그래프는 최대 200개, 프로젝트는 최대 2,000개 노드입니다.');return}if(graphView!=='main'&&['entry','callback','handler','runTimer','process','userEvent','return'].includes(kind)){toast('이 노드는 주 그래프에 배치하세요. 함수 반환은 함수 그래프에서 추가할 수 있습니다.');return}const r=$('canvas').getBoundingClientRect(),p=point||{x:r.width*.45,y:r.height*.35},pos={x:(p.x-camera.x)/camera.z,y:(p.y-camera.y)/camera.z};const n=newNode(kind,{...extra,...(graphView==='main'?{}:{graph:graphView}),x:Math.round(pos.x),y:Math.round(pos.y)});while(graphNodes().some(other=>Math.abs(other.x-n.x)<25&&Math.abs(other.y-n.y)<25)){n.x+=34;n.y+=44}commit(()=>program.nodes.push(n));selected=n.id;selectedEdge=null;renderGraph();setInspector('node');toast('노드 추가 · '+nodeTitle(n));}
function processItems(){return [['process','가상 프로그램 / 프로세스','핸들 · EPROCESS · PID · 유저 VA'],['runTimer','Run 타이머','시뮬레이션 시작 후 ms 단위 트리거'],['userEvent','유저 이벤트','프로세스 종료 · 스레드 · 이미지 · 레지스트리'],...Object.entries(HANDLERS).map(([k,h])=>['handler:'+k,h.title+' Handler',h.returns+' · 호환 서명 전용'])];}
function renderPalette(){let list='';const q=$('nodeSearch').value.toLowerCase();$('modeledOnly').parentElement.hidden=library!=='api';if(library==='api'){let rows=C.exports.filter(e=>(!$('modeledOnly').checked||available.includes(e.id))&&(e.name+' '+e.symbol).toLowerCase().includes(q));$('catalogCount').textContent=rows.length.toLocaleString();if($('modeledOnly').checked){for(const group of [...new Set(available.map(x=>APIS[x].group))]){const items=rows.filter(e=>APIS[e.id]?.group===group);if(items.length)list+='<div class="palette-group">'+esc(group)+'<span>'+items.length+'</span></div>'+items.map(e=>paletteItem('api',e.id,e.name,'EXPORT · '+e.rva,true,e.callable)).join('')}}else{list='<div class="palette-group">현재 PE의 EXPORT <span>'+rows.length+'</span></div>'+rows.slice(0,150).map(e=>paletteItem('api',e.id,e.name,e.callable?(APIS[e.id]?'실행 모델 있음':'계약 모델 미구현'):'데이터 / forwarder · 호출 불가',!!APIS[e.id],e.callable)).join('');if(rows.length>150)list+='<div class="note">검색으로 나머지 '+(rows.length-150)+'개 항목을 찾아보세요.</div>'}}
else if(library==='variable'){const vs=(program.variables||[]).filter(v=>(v.scope==='global'||v.graph===graphView)&&(v.name+' '+v.type).toLowerCase().includes(q));$('catalogCount').textContent=vs.length;list='<div class="palette-group">변수 선언 / 참조</div><div class="button-row"><button data-new-variable="local">+ 지역변수</button><button data-new-variable="global">+ 전역변수</button><button data-new-variable="local" data-container="array">+ 지역배열</button><button data-new-variable="global" data-container="array">+ 전역배열</button><button data-new-variable="local" data-container="struct">+ 지역구조체</button><button data-new-variable="global" data-container="struct">+ 전역구조체</button></div>'+vs.map(v=>paletteItem('variable',v.id,(v.scope==='global'?'전역 · ':'지역 · ')+v.name,aggregateTypeName(v)+' · 초기값 '+v.initial,true,true)).join('')+'<div class="palette-group">변수 연산 · Ref 핀 연결</div>'+[...ACCESS_KINDS,...VARIABLE_OPS].map(k=>paletteItem('variableOp',k,VARIABLE_LABELS[k],k==='arrayElement'?'Index 핀 → 요소 Ref / Value / Address':k==='structField'?'Field 핀 → 필드 Ref / Value / Address':k==='variableGet'?'실행 시점 값 읽기':k==='variableSet'?'Value 핀 → 변수 저장':'Delta 핀 · 변경 전/후 값',true,true)).join('')}else if(library==='function'){const fs=(program.functions||[]).filter(f=>(f.name+' '+f.returnType+' '+f.args.map(a=>a.name).join(' ')).toLowerCase().includes(q));$('catalogCount').textContent=fs.length;list='<div class="palette-group">사용자 드라이버 함수</div><button id="paletteNewFunction" class="function-new">+ 사용자 함수 만들기</button>'+fs.map(f=>'<div class="function-palette-row">'+paletteItem('function',f.id,f.name,f.args.length+'개 인자 → '+f.returnType,true,true)+'<button data-edit-fngraph="'+f.id+'" class="function-edit">그래프 편집 ↗</button></div>').join('')}else if(library==='enum'||library==='define'){const groups=Object.entries(GROUPS).filter(([k,g])=>g.kind===library&&(k+' '+g.members.map(m=>m.name).join(' ')).toLowerCase().includes(q));const globals=library==='define'?(program.defines||[]).filter(d=>d.name.toLowerCase().includes(q)):[];$('catalogCount').textContent=groups.length+globals.length+1;list='<div class="palette-group">'+(library==='enum'?'열거형':'전역 define / 플래그')+'</div>'+paletteItem(library,'custom',library==='enum'?'+ 사용자 enum 만들기':'+ 전역 define 만들기','프로젝트 정의 · 정수 자료형',true,true)+globals.map(d=>paletteItem('define','global:'+d.name,d.name,d.type+' · '+d.value,true,true)).join('')+groups.map(([k,g])=>paletteItem(library,k,k,g.type+' · '+g.members.length+'개 상수',true,true)).join('')}else if(library==='process'){const items=processItems().filter(x=>(x[1]+x[2]).toLowerCase().includes(q));$('catalogCount').textContent=items.length;list='<div class="palette-group">프로세스 / 스케줄 / 통지</div>'+items.map(x=>paletteItem('process',x[0],x[1],x[2],true,true)).join('')}else if(library==='data'){const types=Object.keys(TYPES).filter(t=>t.toLowerCase().includes(q));$('catalogCount').textContent=types.length;list='<div class="palette-group">데이터와 커널 객체</div>'+types.map(t=>paletteItem('data',t,t,TYPES[t].custom?'사용자 정의 구조체 · 필드 직접 지정':TYPES[t].opaque?'opaque 객체 · 모델 저장소':TYPES[t].string?'문자열 / 문자열 기술자':TYPES[t].scalar?TYPES[t].size*8+' bit 값':'명시적 필드',true,true)).join('')}
else {const items=[['entry','DriverEntry','드라이버 진입점 · 한 개만'],['callback','DpcRoutine','타이머 / DPC 콜백 루틴'],['branch','if / else if / else','else if 조건 동적 추가 · 순서 변경'],['for','for 반복문','시작값 / 조건 / 증감 · Index 출력'],['while','while 반복문','매회 조건 평가 · 외부 변수 갱신'],['break','break · 반복 종료','가장 안쪽 반복문의 완료 출력으로'],['continue','continue · 다음 반복','for: 증감 후 조건 / while: 조건'],['calculate','계산 · 정수 연산','실시간 데이터 계산 · + − × ÷ 비트 연산'],['compare','비교 · BOOL 조건','반복 조건 핀에 연결하는 비교 결과'],['return',graphView==='main'?'Return NTSTATUS':'함수 반환',graphView==='main'?'루틴 반환':'함수 반환값 / VOID 반환'],['write','Memory Write','1 / 2 / 4 / 8 byte 쓰기'],['read','Memory Read','1 / 2 / 4 / 8 byte 읽기']].filter(x=>(x[1]+x[2]).toLowerCase().includes(q));$('catalogCount').textContent=items.length;list='<div class="palette-group">실행 흐름 / 메모리 연산</div>'+items.map(x=>paletteItem('flow',x[0],x[1],x[2],true,true)).join('')}
$('paletteList').innerHTML=list||'<div class="note">검색 결과가 없습니다.</div>';document.querySelectorAll('[data-add]').forEach(el=>{el.onclick=()=>fromPalette(el.dataset.kind,el.dataset.add);el.ondragstart=e=>e.dataTransfer.setData('application/x-kernel-node',JSON.stringify({kind:el.dataset.kind,value:el.dataset.add}));});wireFunctionLinks($('paletteList'));$('paletteList').querySelectorAll('[data-new-variable]').forEach(b=>b.onclick=()=>makeVariable(b.dataset.newVariable,b.dataset.container||'scalar'));if($('paletteNewFunction'))$('paletteNewFunction').onclick=makeUserFunction;}
function paletteItem(kind,value,title,subtitle,modeled,callable){return `<button class="palette-item ${kind} ${modeled?'':'unmodeled'}" data-kind="${kind}" data-add="${esc(value)}" draggable="${!!callable}" ${callable?'':'disabled'} title="${esc(title)}"><span class="item-icon">${kind==='api'?'ƒ':kind==='data'?'{}':'⑂'}</span><span class="item-name">${esc(title)}<small>${esc(subtitle)}</small></span><span class="plus">+</span></button>`}
function fromPalette(kind,value,point){if(kind==='variable'){addNode('variable',{variableId:value},point);return}if(kind==='variableOp'){addNode(value,{},point);return}if(kind==='function'){addNode('userCall',{functionId:value},point);return}if(value==='return'&&graphView!=='main'){addNode('functionReturn',{},point);return}if(kind==='enum'||kind==='define'){if(value==='custom'){if(kind==='define'){let d;commit(()=>d=freshDefine(program));addNode('define',{defineName:d.name,valueType:d.type},point);}else addNode('enum',{},point);}else if(value.startsWith('global:'))addNode('define',{defineName:value.slice(7)},point);else addNode(kind,{groupName:value},point);renderPalette();return;}if(kind==='api')addNode('api',{api:value},point);else if(kind==='data')addNode('data',{type:value},point);else{if(value.startsWith('handler:')){addNode('handler',{handlerType:value.slice(8)},point);return}if(value==='entry'&&program.nodes.some(n=>n.kind==='entry')){toast('DriverEntry는 이미 있습니다.');return}addNode(value,{},point)}}
function nodeInputRow(n,p){const link=program.edges.find(e=>e.kind==='data'&&e.to===n.id&&e.in===p.name);return `<div class="param-row">${pin(n,'in',p.name,p.type,!!link)}<span class="label watch-label" role="button" tabindex="0" data-watch-id="${esc(n.id)}" data-watch-name="${esc(p.name)}" data-watch-dir="in" title="일시정지 시 값 확인 · ${esc(p.type)}">${esc(p.label||p.name)}</span>${link?`<span class="linked">← ${esc(link.from+'.'+link.out)}</span>`:p.type.startsWith('VAR:')?'<span class="linked">Ref 연결 필요</span>':parameterControl(n,p,n.params?.[p.name]??p.default??'0',n.id+'::param::'+p.name,resolve,`<input aria-label="${esc(n.id+' '+p.name)}" data-param="${esc(p.name)}" data-owner="${n.id}" value="${esc(n.params?.[p.name]??p.default??'0')}">`)}</div>`}
function nodeHtml(n){const spec=ports(n),model=APIS[n.api],item=exported.get(n.api),isExec=!['arrayElement','structField','variable','data','enum','define','calculate','compare','entry','functionEntry','callback','handler','runTimer'].includes(n.kind);return `<article class="node ${n.kind}" id="node-${esc(n.id)}" data-node="${esc(n.id)}" style="left:${n.x}px;top:${n.y}px" aria-label="${esc(nodeTitle(n)+' '+n.id)}">${isExec?pin(n,'in','exec','exec',true,'exec-in'):''}<div class="node-header" data-drag="${esc(n.id)}"><span class="type-icon">${n.kind==='api'?'ƒ':n.kind==='enum'?'E':n.kind==='define'?'#':n.kind==='data'?'{}':n.kind==='branch'?'⑂':'▶'}</span><b>${esc(nodeTitle(n))}</b>${n.breakpoint?'<span class="breakpoint">●</span>':''}<small>${esc(n.id.split('_').at(-1))}</small></div><div class="node-body"><div class="node-sub"><span>${n.kind==='api'?(model?'EXPORT · '+esc(model.group):'모델 미구현'):n.kind==='entry'?'NTSTATUS DriverEntry(...)':n.kind==='callback'?'CustomTimerDpc · IRQL 2':n.kind==='handler'?'PASSIVE_LEVEL · '+(HANDLERS[n.handlerType]?.returns||'VOID'):n.kind==='process'?'VIRTUAL USER PROCESS':n.kind==='runTimer'?String(n.delayMs)+'ms AFTER START':n.kind==='variable'?(variableById(program,n.variableId)?.scope==='global'?'SHARED GLOBAL VARIABLE':'INVOCATION LOCAL VARIABLE'):n.kind==='data'?(TYPES[n.type]?.opaque?'OPAQUE MODEL OBJECT':TYPES[n.type]?.string?'STRING DATA':'TYPED DATA'):['enum','define'].includes(n.kind)?'CONSTANT DATA · '+nodeValueType(n):ACCESS_KINDS.includes(n.kind)?'AGGREGATE DATA ACCESS':PURE_KINDS.includes(n.kind)?'LIVE DATA EXPRESSION':'EXECUTION FLOW'}</span><span>${item?.rva||''}</span></div>${n.api==='DbgPrint'?'<div class="print-node-preview">'+esc(n.formatText||'Format 핀 문자열 사용')+'</div>':''}${LOOP_KINDS.includes(n.kind)?'<div class="loop-repeat-bar">'+pin(n,'in','repeat','exec',program.edges.some(e=>e.kind==='exec'&&e.to===n.id&&e.in==='repeat'),'loop-repeat-in')+'<span>↻ Repeat · 본문 끝에서 복귀</span></div><div class="loop-condition-summary">'+esc(n.conditionMode==='boolean'||program.edges.some(e=>e.kind==='data'&&e.to===n.id&&e.in==='Condition')?'Condition BOOL 사용':n.kind==='for'?'Index '+(n.op||'<')+' Limit':'Left '+(n.op||'<')+' Right')+'</div>':''}${['break','continue'].includes(n.kind)?'<div class="loop-control-note">'+esc(n.kind==='break'?'가장 안쪽 반복문의 완료 출력으로':'가장 안쪽 반복문으로 복귀')+'</div>':''}${LOOP_KINDS.includes(n.kind)?'<div data-loopview="'+n.id+'">'+loopView(engine,n.id)+'</div>':''}${['enum','define'].includes(n.kind)?'<div class="node-data-value">'+esc(constantSummary(n,program,resolve))+'</div>':''}${n.kind==='variable'?'<div class="variable-live" data-variableview="'+n.id+'">'+variableNodeLive(n)+'</div>':''}${n.kind==='data'?'<div class="node-data-value">'+esc(TYPES[n.type]?.opaque?'객체 저장소 · 초기화 API 연결':n.type==='CUSTOM_STRUCT'?n.fields:n.value)+'</div>':''}${n.kind==='branch'?branchNodeBody(n):spec.inputs.map(p=>nodeInputRow(n,p)).join('')}${spec.outputs.filter(p=>p.type!=='VOID').map(p=>`<div class="param-row output"><span class="label watch-label" role="button" tabindex="0" data-watch-id="${esc(n.id)}" data-watch-name="${esc(p.name)}" data-watch-dir="out">${esc(p.label||p.name)} <small>${esc(p.type)}</small></span>${pin(n,'out',p.name,p.type,program.edges.some(e=>e.kind==='data'&&e.from===n.id&&e.out===p.name))}</div>`).join('')}<div class="node-return" data-result="${n.id}"></div>${n.kind==='process'?'<div class="process-view" data-processview="'+n.id+'">'+processView(n)+'</div>':''}</div>${spec.exec.length&&n.kind!=='branch'?'<div class="exec-outs">'+spec.exec.map(p=>`<div class="exec-out">${esc(p==='then'?'다음':p==='elseIf'?'else if':FLOW_LABELS[p]||p)}${pin(n,'out',p,'exec',program.edges.some(e=>e.kind==='exec'&&e.from===n.id&&e.out===p))}</div>`).join('')+'</div>':''}</article>`;}
function pin(n,direction,name,type,linked,cls=''){return `<button class="pin ${type==='exec'?'exec':''} ${linked?'connected':''} ${cls}" data-pin data-id="${esc(n.id)}" data-dir="${direction}" data-name="${esc(name)}" data-type="${esc(type)}" aria-label="${esc(n.id+' '+direction+' '+name+' '+type)}" title="${esc(name+' : '+type)}"></button>`}
function renderGraph(){closeNodeMenu();hideArgumentTip();graphGesture.end(null,'render');renderGraphNavigation();drawMini();$('nodes').innerHTML=graphNodes().map(nodeHtml).join('');$('graphStats').textContent=`${graphNodes().length} nodes · ${graphEdges().length} links`;$('graphTitle').textContent=$('projectName').value+'.sys / '+(functionById(program,graphView)?.name||'DriverEntry');document.querySelectorAll('[data-node]').forEach(el=>{el.addEventListener('click',e=>{if(e.target.closest('input,select,label,[data-pin],[data-watch-name]'))return;selected=el.dataset.node;selectedEdge=null;highlight();setInspector('node')});el.addEventListener('contextmenu',e=>{e.preventDefault();e.stopPropagation();showNodeMenu(el.dataset.node,e.clientX,e.clientY)})});document.querySelectorAll('[data-param]').forEach(el=>{el.oninput=()=>{const n=program.nodes.find(n=>n.id===el.dataset.owner);if(n.kind==='structField'&&el.dataset.param==='Field')commit(()=>{n.params.Field=el.value;reconcileVariablePins(program,enginePorts,compatible)});else edit(()=>n.params[el.dataset.param]=el.value)};el.onpointerdown=e=>e.stopPropagation()});document.querySelectorAll('[data-pin]').forEach(el=>{el.onpointerdown=e=>{e.stopPropagation();if(e.button!==0)return;graphGesture.begin(e,{type:'pin',pin:pinInfo(el)})};el.onclick=e=>{e.stopPropagation();selectPin(pinInfo(el))}});wireBranchControls($('nodes'));bindConstantControls($('nodes'),program,commit,resolve);transform();requestAnimationFrame(()=>{drawWires();highlight()})}
function pinInfo(el){return {id:el.dataset.id,dir:el.dataset.dir,name:el.dataset.name,type:el.dataset.type}}
function selectPin(p){if(!connect){connect=p;showConnect();return}if(connect.id===p.id&&connect.dir===p.dir&&connect.name===p.name){connect=null;showConnect();return}completeConnection(connect,p)}
function completeConnection(a,b){if(a.dir===b.dir){connect=b;showConnect();return}const from=a.dir==='out'?a:b,to=a.dir==='in'?a:b;if(from.id===to.id&&!(from.type==='exec'&&from.name==='body'&&to.name==='repeat'&&LOOP_KINDS.includes(program.nodes.find(n=>n.id===to.id)?.kind))){toast('같은 노드의 핀은 연결할 수 없습니다.');return}const exec=from.type==='exec';if(exec!==(to.type==='exec')||!exec&&!compatible(from.type,to.type)){toast(`자료형 불일치: ${from.type} → ${to.type}`);return}commit(()=>{program.edges=program.edges.filter(e=>!(exec?e.kind==='exec'&&e.from===from.id&&e.out===from.name:e.kind==='data'&&e.to===to.id&&e.in===to.name));program.edges.push({id:unique('edge'),kind:exec?'exec':'data',from:from.id,out:from.name,to:to.id,in:to.name})});connect=null;showConnect();toast('연결 완료 · '+from.name+' → '+to.name)}
function showConnect(){$('connectionHint').hidden=!connect;$('connectionHint').textContent=connect?`${connect.id}.${connect.name} (${connect.type}) → 연결할 핀을 클릭 · Esc 취소`:'';document.querySelectorAll('[data-pin]').forEach(el=>el.classList.toggle('armed',connect&&el.dataset.id===connect.id&&el.dataset.name===connect.name&&el.dataset.dir===connect.dir))}
function transform(){$('scene').style.transform=`translate(${camera.x}px,${camera.y}px) scale(${camera.z})`;$('zoomLabel').textContent=Math.round(camera.z*100)+'%';$('canvas').style.backgroundSize=(20*camera.z)+'px '+(20*camera.z)+'px';$('canvas').style.backgroundPosition=camera.x+'px '+camera.y+'px';}
function portPosition(id,dir,name){const el=[...document.querySelectorAll('[data-pin]')].find(p=>p.dataset.id===id&&p.dataset.dir===dir&&p.dataset.name===name);if(!el)return null;const r=el.getBoundingClientRect(),c=$('canvas').getBoundingClientRect();return {x:(r.left+r.width/2-c.left-camera.x)/camera.z,y:(r.top+r.height/2-c.top-camera.y)/camera.z}}
function drawWires(){let html='';for(const edge of graphEdges()){const a=portPosition(edge.from,'out',edge.out),b=portPosition(edge.to,'in',edge.in);if(!a||!b)continue;const d=edge.kind==='exec'?`M${a.x},${a.y} C${a.x},${a.y+Math.max(55,Math.abs(b.y-a.y)*.45)} ${b.x},${b.y-Math.max(55,Math.abs(b.y-a.y)*.45)} ${b.x},${b.y}`:`M${a.x},${a.y} C${a.x+Math.max(60,Math.abs(b.x-a.x)*.4)},${a.y} ${b.x-Math.max(60,Math.abs(b.x-a.x)*.4)},${b.y} ${b.x},${b.y}`;html+=`<path d="${d}" class="wire-halo"/><path d="${d}" class="wire ${edge.kind} ${selectedEdge===edge.id?'selected':''}" data-wire="${esc(edge.id)}"/>`}html+=loopTransferWire();$('wires').innerHTML=html;document.querySelectorAll('[data-wire]').forEach(el=>el.onclick=e=>{e.stopPropagation();selectedEdge=el.dataset.wire;selected=null;drawWires();setInspector('node');highlight()});}
function fit(){const r=$('canvas').getBoundingClientRect();if(!graphNodes().length)return;const minX=Math.min(...graphNodes().map(n=>n.x)),minY=Math.min(...graphNodes().map(n=>n.y)),maxX=Math.max(...graphNodes().map(n=>n.x+280)),maxY=Math.max(...graphNodes().map(n=>n.y+(document.getElementById('node-'+n.id)?.offsetHeight||210)+30));camera.z=Math.max(.25,Math.min(1,(r.width-80)/(maxX-minX),(r.height-80)/(maxY-minY)));camera.x=(r.width-(maxX-minX)*camera.z)/2-minX*camera.z;camera.y=30-minY*camera.z;transform();drawWires();persist()}
function drawMini(){if(!graphNodes().length)return;const x=Math.min(...graphNodes().map(n=>n.x))-30,y=Math.min(...graphNodes().map(n=>n.y))-30,w=Math.max(...graphNodes().map(n=>n.x+300))-x,h=Math.max(...graphNodes().map(n=>n.y+240))-y;$('miniMap').setAttribute('viewBox',[x,y,w,h].join(' '));$('miniMap').innerHTML=graphNodes().map(n=>`<rect data-mini="${esc(n.id)}" data-kind="${esc(n.kind)}" x="${n.x}" y="${n.y}" width="268" height="160" rx="12" fill="${n.kind==='data'?'#8e79b6':'#49647b'}"/>`).join('');document.querySelectorAll('[data-mini]').forEach(el=>el.onclick=e=>{e.stopPropagation();selected=el.dataset.mini;selectedEdge=null;focusNode(selected,true);highlight();setInspector('node')});}
function arrange(){commit(()=>{const placed=new Set(),roots=graphNodes().filter(n=>['entry','functionEntry','callback','handler','runTimer'].includes(n.kind));roots.forEach((root,ri)=>{let layer=[root],depth=0,layerY=40;while(layer.length&&depth<200){const next=[];layer=layer.filter(n=>!placed.has(n.id));layer.forEach((n,i)=>{placed.add(n.id);n.x=430+ri*1000+(i-(layer.length-1)/2)*330;n.y=layerY;graphEdges().filter(e=>e.kind==='exec'&&e.from===n.id).forEach(e=>{const other=graphNodes().find(n=>n.id===e.to);if(other&&!placed.has(other.id)&&!next.includes(other))next.push(other)})});layerY+=Math.max(330,...layer.map(n=>(document.getElementById('node-'+n.id)?.offsetHeight||250)+80));layer=next;depth++;}});let data=0,extra=0;graphNodes().filter(n=>!placed.has(n.id)).forEach(n=>{n.x=['arrayElement','structField','variable','data','enum','define','calculate','compare'].includes(n.kind)?40:1450;n.y=250+(['arrayElement','structField','variable','data','enum','define','calculate','compare'].includes(n.kind)?data++:extra++)*240;});},false);requestAnimationFrame(fit)}
function focusNode(id,zoom=false){const n=program.nodes.find(n=>n.id===id);if(!n)return;if(graphOf(n)!==graphView)switchGraph(graphOf(n),{nodeId:id,runtime:true});const r=$('canvas').getBoundingClientRect(),el=document.getElementById('node-'+n.id),width=el?.offsetWidth||280,height=el?.offsetHeight||220;if(zoom)camera.z=Math.max(.22,Math.min(.9,(r.height-40)/height,(r.width-40)/width));camera.x=r.width/2-(n.x+width/2)*camera.z;camera.y=r.height/2-(n.y+height/2)*camera.z;transform();drawWires();}

function highlight(){let changed=false;document.querySelectorAll('[data-variableview]').forEach(el=>{const n=program.nodes.find(n=>n.id===el.dataset.variableview),text=variableNodeLive(n);if(el.innerHTML!==text){el.innerHTML=text;changed=true}});document.querySelectorAll('[data-node]').forEach(el=>{el.classList.toggle('selected',selected===el.dataset.node);el.classList.toggle('running',engine?.current===el.dataset.node&&['running','paused'].includes(engine?.state));el.classList.toggle('fault',engine?.error?.node===el.dataset.node);el.classList.toggle('visited',!!engine?.visited.has(el.dataset.node));const r=el.querySelector('[data-result]'),out=engine?.functions.outputsForGraph(graphView).get(el.dataset.node);if(r){const n=program.nodes.find(n=>n.id===el.dataset.node),record=engine?.functions.lastByGraph.get(graphView);const text=n?.kind==='functionEntry'&&out?(functionById(program,graphView)?.args||[]).map(a=>a.name+' = '+fmt(out[a.id])).join(' · '):n?.kind==='functionReturn'&&record?.returnNode===n.id?'↩ '+fmt(record.returnValue):out&&'Return'in out?'↳ '+fmt(out.Return):out&&'Value'in out?'= '+fmt(out.Value):'';if(r.textContent!==text){r.textContent=text;changed=true}}});document.querySelectorAll('[data-loopview]').forEach(el=>{const html=loopView(engine,el.dataset.loopview);if(el.innerHTML!==html){el.innerHTML=html;changed=true;}});document.querySelectorAll('[data-wire]').forEach(el=>{const e=program.edges.find(e=>e.id===el.dataset.wire);el.classList.toggle('active',e?.kind==='exec'&&engine?.lastPorts.get(e.from)===e.out&&engine?.visited.has(e.from))});if(changed)requestAnimationFrame(drawWires);document.querySelectorAll('[data-mini]').forEach(el=>el.setAttribute('fill',engine?.error?.node===el.dataset.mini?'#ed7084':engine?.current===el.dataset.mini?'#7be0bc':el.dataset.kind==='data'?'#8e79b6':'#49647b'));}
function field(label,value,attrs=''){return `<label class="field">${esc(label)}<input value="${esc(value)}" ${attrs}></label>`}
function renderInspector(){const n=program.nodes.find(n=>n.id===selected),edge=program.edges.find(e=>e.id===selectedEdge);let html='';if(inspector==='function'){html=definitionInspector(program,selectedFunction(),TYPES)}else if(inspector==='validation'){html=validationInspector()}else if(inspector==='settings'){html=`<div class="eyebrow">KERNEL ENVIRONMENT</div><h2>시뮬레이터 설정</h2><p>설정은 새 시뮬레이션부터 적용됩니다.</p><h3>가상 커널 메모리</h3><label class="field">메모리 크기<select data-setting="memoryMB">${[1,4,8,16,32,64,128].map(v=>`<option value="${v}" ${Number(settings.memoryMB)===v?'selected':''}>${v} MB</option>`).join('')}</select></label><p>풀·객체·문자열 저장소가 이 한도를 공유합니다. 실제 바이트 배열을 사용하며 풀은 해제 후 재사용합니다.</p><h3>유저 주소 공간</h3><label class="field">전체 유저 커밋 한도<select data-setting="userMemoryMB">${[4,16,32,64,128].map(v=>`<option value="${v}" ${Number(settings.userMemoryMB||64)===v?'selected':''}>${v} MB</option>`).join('')}</select></label><p>프로세스마다 별도 VA와 페이지 맵을 사용합니다. 유저 메모리는 attach된 현재 주소 공간에서만 커널이 직접 접근할 수 있습니다.</p><h3>DriverEntry 인자</h3><label class="field">DriverEntry 인자 생성<select data-setting="entryMode"><option value="random" ${settings.entryMode==='random'?'selected':''}>Seed 기반 랜덤</option><option value="manual" ${settings.entryMode==='manual'?'selected':''}>사용자 지정</option></select></label>${field('랜덤 Seed',settings.seed,'data-setting="seed"')}${field('DriverObject 가상 주소',settings.driverAddress,'data-setting="driverAddress"')}${field('RegistryPath (랜덤 모드에서는 Seed 접미사 추가)',settings.registryPath,'data-setting="registryPath"')}<p>DriverObject는 할당된 모델 객체를 가리키는 가상 커널 주소입니다. RegistryPath는 UNICODE_STRING으로 전달합니다.</p><label class="field"><span><input type="checkbox" data-setting="forceIntegrity" ${settings.forceIntegrity!==false?'checked':''} style="width:auto"> 가상 드라이버 FORCE_INTEGRITY</span></label><p>ProcessNotifyEx 등록의 이미지 무결성 조건을 모델링합니다.</p><h3>실행</h3>${field('한 모델 단계당 가상 시간 (ms)',settings.stepMs,'type="number" min="50" max="2000" data-setting="stepMs"')}${field('최대 모델 단계 수',settings.maxSteps,'type="number" min="100" max="100000" data-setting="maxSteps"')}<label class="field"><span><input type="checkbox" data-setting="follow" ${settings.follow?'checked':''} style="width:auto"> 실행 노드가 화면 밖이면 따라가기</span></label><h3>가상 하드웨어</h3><div class="note">BAR0: 0xF0000000–0xF0000FFF<br>+0x00: DOORBELL (32 bit)<br>+0x04: STATUS (32 bit, 읽기)<br>Doorbell write → 250ms 뒤 완료 및 가상 IRQ 증가. 특정 GPU/PCI 장치의 명세가 아닙니다.</div>`}
else if(inspector==='runtime'){const mem=engine?.mem,blocks=mem?.blocks.filter(b=>!b.freed)||[];html=`<div class="eyebrow">LIVE ENVIRONMENT</div><h2>${esc(engine?.state?.toUpperCase()||'READY')}</h2><p>${engine?'실행 단계 '+engine.steps+' · 노드 '+(engine.current||'대기'):'시작 버튼을 누르면 가상 커널 환경을 생성합니다.'}</p><h3>커널 메모리</h3><div>${mem?(mem.used/1024).toFixed(1):0} KB / ${settings.memoryMB} MB</div><div class="memory-meter"><div style="width:${mem?mem.used/mem.bytes.length*100:0}%"></div></div><p>${blocks.filter(b=>b.kind==='pool').length} live pool blocks · ${blocks.filter(b=>b.kind==='object').length} model objects</p><h3>DriverEntry 인자</h3><div class="note">DriverObject<br>${esc(engine?.entryDisplay?.DriverObject||'—')}<br>RegistryPath<br>${esc(engine?.entryDisplay?.RegistryPath||'—')}</div>${engine?.loops.records.length?'<h3>반복문 실행</h3>'+engine.loopFrames.map(f=>'<div data-loopview="'+f.node+'">'+loopView(engine,f.node)+'</div>').join(''):''}<h3>타이머 / 대기 큐</h3>${engine?.queue.length?engine.queue.slice(0,20).map(t=>`<div class="state-timer">${esc(t.kind)} · ${Math.max(0,t.at-engine.time).toFixed(0)}ms 남음</div>`).join(''):'<p>예약된 이벤트 없음</p>'}${engine?.wait?'<div class="note">스레드가 dispatcher 대기 중입니다.</div>':''}${engine?.error?`<h3>최근 중단</h3><div class="note warning">${esc(engine.error.reason)}<br>${esc(engine.error.status)}</div>`:''}<h3>버전 근거</h3><p class="mono">SHA256<br>${esc(C.sha256)}<br>PDB ${esc(C.pdb.guid)} · age ${C.pdb.age}</p>`}
else if(edge){html=`<div class="eyebrow">SELECTED CONNECTION</div><h2>${edge.kind==='exec'?'실행 연결':'데이터 연결'}</h2><div class="note">${esc(edge.from+'.'+edge.out)}<br>↓<br>${esc(edge.to+'.'+edge.in)}</div><button id="deleteEdge" class="danger">연결 삭제</button>`}
else if(n){const spec=ports(n),item=exported.get(n.api),api=APIS[n.api];html=`<div class="eyebrow">${esc(n.kind.toUpperCase())} NODE / ${esc(n.id)}</div><h2>${esc(nodeTitle(n))}</h2><span class="type-badge">${esc(n.kind==='api'?(api?.ret||'MODEL REQUIRED'):VARIABLE_KINDS.includes(n.kind)?(n.kind==='variable'?aggregateTypeName(variableById(program,n.variableId)):n.valueType||'LARGE_INTEGER'):['enum','define'].includes(n.kind)?nodeValueType(n):PURE_KINDS.includes(n.kind)?(n.kind==='compare'?'BOOLEAN':'LARGE_INTEGER'):n.type||'EXECUTION')}</span>${item?`<p>EXPORT #${item.ordinal} · RVA ${item.rva}</p>`:''}${n.kind==='api'&&!api?'<div class="note warning">PE에서 확인한 EXPORT입니다. 아직 실행 모델과 인자 계약이 없으므로 그래프 실행을 차단합니다.</div>':''}${n.kind==='entry'?'<p>인자는 설정 패널에서 랜덤 또는 직접 지정할 수 있습니다. 실행은 PASSIVE_LEVEL에서 시작합니다.</p>':''}${n.kind==='callback'?'<p>Routine 출력을 KeInitializeDpc의 DeferredRoutine에 연결하세요. DPC 실행 시 IRQL은 DISPATCH_LEVEL입니다.</p>':''}${['process','handler','runTimer','userEvent'].includes(n.kind)?processInspector(n):''}${n.kind==='enum'?enumInspector(n,resolve):n.kind==='define'?defineInspector(n,program,resolve):''}${VARIABLE_KINDS.includes(n.kind)?variableInspector(n,program,TYPES):''}${n.kind==='userCall'?callInspector(n,program):''}${n.kind==='functionEntry'?'<p>인자는 호출마다 별도 값으로 전달됩니다. 오른쪽 인자 핀을 함수 본문에 연결하세요.</p>':''}${n.kind==='functionReturn'?'<p>반환값을 연결하면 호출 위치의 Return 핀에 전달하고 호출 노드의 다음 실행으로 복귀합니다.</p>':''}${n.kind==='data'?dataInspector(n):''}${n.kind==='branch'?branchInspector(n):''}${n.api==='DbgPrint'?printInspector(n,esc):''}${loopInspector(n)}${['read','write'].includes(n.kind)?`<label class="field">접근 폭<select data-nodefield="width">${[1,2,4,8].map(v=>`<option ${Number(n.width)===v?'selected':''}>${v}</option>`).join('')}</select></label><p>가상 메모리 접근 명령입니다. 커널 API 호출 노드와 구분되며 범위·해제·IRQL을 검사합니다.</p>`:''}${spec.inputs.length&&n.kind!=='branch'?'<h3>인자 / 데이터 입력</h3>'+spec.inputs.map(p=>paramInspector(n,p)).join(''):''}${spec.exec.length?'<h3>실행 흐름</h3>'+spec.exec.map(out=>`<label class="field">${esc(out==='then'?'다음 실행':n.kind==='branch'?branchLabel(n,out):FLOW_LABELS[out]||out)}<select data-exec="${out}"><option value="">연결되지 않음</option>${executionOptions(n,out)}</select></label>`).join(''):''}<div class="button-row"><button id="toggleBreakpoint">${n.breakpoint?'● 중단점 해제':'○ 중단점 추가'}</button>${!['entry','functionEntry'].includes(n.kind)?'<button id="duplicate">복제</button><button id="deleteNode" class="danger">삭제</button>':''}<button id="focusNode">노드 확대</button></div>${n.kind==='api'?evidence(n):''}`}
else html=`<div class="eyebrow">GRAPH INSPECTOR</div><h2>커널 흐름을<br>직접 연결하세요.</h2><p>노드를 선택하면 인자와 실행 연결을 수정할 수 있습니다.</p><div class="note">① DriverEntry에서 시작<br>② EXPORT API 배치<br>③ 자료형 출력 → 인자 연결<br>④ 실행 핀을 다음 노드로 연결</div><h3>핀이 의미하는 것</h3><p>◇ 흰색 사각 핀은 실행 순서<br><span style="color:var(--purple)">●</span> 색상 핀은 자료형을 가진 데이터<br>입력에 연결이 없으면 직접 입력한 값을 사용합니다.</p><h3>모델 범위</h3><p>${available.length}개 EXPORT에 실행 계약이 있습니다. 전체 ${C.exports.length.toLocaleString()}개 EXPORT 항목을 카탈로그에서 찾아볼 수 있습니다. 내부 데이터 EXPORT는 API로 호출할 수 없습니다.</p><button id="openSettings">커널 환경 설정 →</button>`;
$('inspectorBody').innerHTML=html;wireInspector(n);}
function ops(value){return ['!=','==','>','>=','<','<=','NT_SUCCESS','&'].map(op=>`<option value="${esc(op)}" ${value===op?'selected':''}>${esc(op)}</option>`).join('')}
function loopTransferWire(){const transfer=engine?.loops.transfer;if(!transfer||engine.time-transfer.time>1400)return '';const from=program.nodes.find(n=>n.id===transfer.from),el=document.getElementById('node-'+transfer.from),to=portPosition(transfer.to,transfer.mode==='break'?'out':'in',transfer.mode==='break'?'after':'repeat');if(!from||!el||!to)return '';const x=from.x+el.offsetWidth/2,y=from.y+el.offsetHeight,d=`M${x},${y} C${x},${y+65} ${to.x-80},${to.y} ${to.x},${to.y}`;return `<path d="${d}" class="wire-halo"/><path d="${d}" class="wire implicit"/><text x="${x+8}" y="${y+20}" class="loop-transfer-label">${esc(transfer.mode)}</text>`;}
function executionOptions(n,out){const edge=program.edges.find(e=>e.kind==='exec'&&e.from===n.id&&e.out===out),options=[];for(const target of graphNodes()){if(['arrayElement','structField','variable','data','enum','define','calculate','compare','entry','functionEntry','callback','handler','runTimer'].includes(target.kind))continue;if(target.id!==n.id)options.push({id:target.id,input:'exec',value:target.id,label:nodeTitle(target)+' · '+target.id});if(LOOP_KINDS.includes(target.kind)&&(target.id!==n.id||out==='body'))options.push({id:target.id,input:'repeat',value:target.id+'::repeat',label:'↻ '+nodeTitle(target)+' · Repeat · '+target.id});}return options.map(o=>`<option value="${esc(o.value)}" ${edge?.to===o.id&&(edge.in||'exec')===o.input?'selected':''}>${esc(o.label)}</option>`).join('');}
function branchActions(n,c,index){return c.id==='if'?'':`<span class="branch-actions"><button data-branch-move="${n.id}::${c.id}::-1" aria-label="else if ${index} 위로" ${index===1?'disabled':''}>↑</button><button data-branch-move="${n.id}::${c.id}::1" aria-label="else if ${index} 아래로" ${index===elseIfs(n).length?'disabled':''}>↓</button><button data-branch-remove="${n.id}::${c.id}" aria-label="else if ${index} 삭제">×</button></span>`;}
function branchAddButton(n){return `<button class="branch-add" data-branch-add="${n.id}" ${elseIfs(n).length>=MAX_ELSE_IFS?'disabled':''}>+ else if 추가</button>`;}
function branchNodeBody(n){return branchCases(n).map((c,i)=>`<section class="branch-case"><div class="branch-case-head"><b>${esc(branchLabel(n,c.id))}</b>${branchActions(n,c,i)}${pin(n,'out',c.id,'exec',program.edges.some(e=>e.kind==='exec'&&e.from===n.id&&e.out===c.id))}</div><select class="branch-op" aria-label="${esc(n.id+' '+branchLabel(n,c.id)+' 비교')}" data-branch-op="${n.id}::${c.id}">${ops(c.op)}</select>${[c.left,...(c.op==='NT_SUCCESS'?[]:[c.right])].map(name=>nodeInputRow(n,{name,label:name===c.left?'왼쪽 값':'오른쪽 값',type:'ANY',default:'0'})).join('')}</section>`).join('')+branchAddButton(n)+`<div class="branch-else"><b>else</b>${pin(n,'out','else','exec',program.edges.some(e=>e.kind==='exec'&&e.from===n.id&&e.out==='else'))}</div>`;}
function branchInspector(n){return '<h3>분기 조건 · 위에서 아래로 평가</h3>'+branchCases(n).map((c,i)=>`<section class="branch-inspect-case"><div class="branch-case-head"><b>${esc(branchLabel(n,c.id))}</b>${branchActions(n,c,i)}</div><label class="field">${esc(branchLabel(n,c.id))} 비교<select data-branch-op="${n.id}::${c.id}">${ops(c.op)}</select></label>${[c.left,...(c.op==='NT_SUCCESS'?[]:[c.right])].map(name=>paramInspector(n,{name,label:name===c.left?'왼쪽 값':'오른쪽 값',type:'ANY',default:'0'})).join('')}</section>`).join('')+branchAddButton(n)+'<p>처음 참인 조건 한 개만 실행합니다. 모두 거짓이면 else로 진행합니다. 조건 순서를 바꿔도 기존 연결을 유지합니다. NT_SUCCESS는 왼쪽 값만 검사합니다.</p>';}
function wireBranchControls(scope){scope.querySelectorAll('[data-branch-add]').forEach(el=>el.onclick=event=>{event.stopPropagation();const n=program.nodes.find(n=>n.id===el.dataset.branchAdd);try{commit(()=>addElseIf(n));}catch(e){toast(e.message)}});scope.querySelectorAll('[data-branch-remove]').forEach(el=>el.onclick=event=>{event.stopPropagation();const [id,condition]=el.dataset.branchRemove.split('::'),n=program.nodes.find(n=>n.id===id);commit(()=>removeElseIf(program,n,condition));});scope.querySelectorAll('[data-branch-move]').forEach(el=>el.onclick=event=>{event.stopPropagation();const [id,condition,direction]=el.dataset.branchMove.split('::'),n=program.nodes.find(n=>n.id===id);commit(()=>moveElseIf(n,condition,Number(direction)));});scope.querySelectorAll('[data-branch-op]').forEach(el=>el.onchange=()=>{const [id,condition]=el.dataset.branchOp.split('::'),n=program.nodes.find(n=>n.id===id);commit(()=>{if(condition==='if')n.op=el.value;else{n.elseIfs=elseIfs(n).map(c=>({...c}));n.elseIfs.find(c=>c.id===condition).op=el.value;}});});}
function wireDefinitionInspector(n){
 const protect=fn=>{try{fn()}catch(e){toast(e.message);renderInspector()}};
 const name=$('inspectorBody').querySelector('[data-enum-name]');if(name)name.oninput=()=>edit(()=>n.enumName=name.value);
 document.querySelectorAll('[data-member-index]').forEach(el=>{el.oninput=()=>edit(()=>{const m=n.members[Number(el.dataset.memberIndex)],old=m.name;m[el.dataset.memberField]=el.value;if(el.dataset.memberField==='name'&&n.member===old)n.member=el.value;const choice=$('inspectorBody').querySelector('[data-nodefield="member"]');if(choice)choice.innerHTML=n.members.map(m=>'<option '+(m.name===n.member?'selected':'')+'>'+esc(m.name)+'</option>').join('');});});
 document.querySelectorAll('[data-remove-member]').forEach(el=>el.onclick=()=>{if(n.members.length<=1){toast('enum에는 한 개 이상의 항목이 필요합니다.');return}commit(()=>{n.members.splice(Number(el.dataset.removeMember),1);if(!n.members.some(m=>m.name===n.member))n.member=n.members[0].name;});});
 if($('addEnumMember'))$('addEnumMember').onclick=()=>{if(n.members.length>=100){toast('enum 항목은 최대 100개입니다.');return}commit(()=>{let i=n.members.length;while(n.members.some(m=>m.name==='Item'+i))i++;n.members.push({name:'Item'+i,value:String(i)});});};
 const ref=$('inspectorBody').querySelector('[data-global-ref]');if(ref)ref.onchange=()=>commit(()=>{n.defineName=ref.value;n.valueType=program.defines.find(d=>d.name===ref.value).type;});
 if($('newGlobalDefine'))$('newGlobalDefine').onclick=()=>commit(()=>{const d=freshDefine(program);n.defineName=d.name;n.valueType=d.type;});
 document.querySelectorAll('[data-def-field]').forEach(el=>{const change=()=>protect(()=>{const d=program.defines.find(d=>d.name===n.defineName),key=el.dataset.defField,value=el.value;if(key==='name'&&Object.hasOwn(CONSTANTS,value))throw new Error('기본 WDK 상수 이름과 중복됩니다.');if(key==='name'){
   // Validate on a clone before committing, preserving undo if the name is invalid.
   renameDefine(structuredClone(program),d.name,value);commit(()=>renameDefine(program,d.name,value));
  }else if(key==='type')commit(()=>{d.type=value;program.nodes.filter(x=>x.defineName===d.name).forEach(x=>x.valueType=value);});
  else if(key==='groupName')commit(()=>{d.groupName=value;if(value)d.value=GROUPS[value].members[0]?.name||'0';});
  else edit(()=>d.value=value);
 });if(el.dataset.defField==='name'){if($('applyDefineName'))$('applyDefineName').onclick=change;el.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();change();}};}else if(el.dataset.defField==='value')el.oninput=change;else el.onchange=change;});
}
function dataInspector(n){const t=TYPES[n.type];if(t.opaque)return '<div class="note">객체 저장소를 만들고 초기화 API에 연결하세요. 내부 구조체 필드 오프셋을 가정하지 않는 opaque 모델입니다.</div>';if(t.custom)return field('구조체 크기 (bytes)',n.size,'data-nodefield="size" type="number" min="1" max="1048576"')+`<label class="field">필드 정의 JSON<textarea data-nodefield="fields">${esc(n.fields)}</textarea></label><p>예: {"Count":{"offset":0,"width":4,"value":"7"}}. 명시한 오프셋과 폭으로 가상 메모리에 기록합니다.</p>`;if(t.fields&&!t.string)return Object.keys(t.fields).map(k=>{const g=n.type==='OBJECT_ATTRIBUTES'&&k==='Attributes'?'OBJECT_ATTRIBUTES_FLAGS':t.fields[k][0]==='NTSTATUS'?'NTSTATUS':t.fields[k][0]==='BOOLEAN'?'BOOLEAN':null;return g?'<div class="field">'+esc(k)+constantControl(g,n.values?.[k]??t.defaults?.[k]??'0',n.id+'::struct::'+k,resolve)+'</div>':field(k,n.values?.[k]??t.defaults?.[k]??'0',`data-structfield="${k}"`);}).join('');if(t.scalar&&['BOOLEAN','NTSTATUS'].includes(n.type))return constantControl(n.type,n.value,n.id+'::scalar',resolve);return `<label class="field">${t.string?'문자열':'값 / 상수 / 태그'}<${t.string?'textarea':'input'} data-nodefield="value" ${t.string?'':'value="'+esc(n.value)+'"'}>${t.string?esc(n.value):''}${t.string?'</textarea>':''}</label>`+(t.string?'<p>UNICODE_STRING / ANSI_STRING의 길이와 버퍼 포인터는 모델이 자동으로 만듭니다.</p>':'<p>예: 256, 0x100, STATUS_SUCCESS, POOL_FLAG_NON_PAGED, \'Demo\'</p>');}
function paramInspector(n,p){const e=program.edges.find(e=>e.kind==='data'&&e.to===n.id&&e.in===p.name),options=[];for(const x of graphNodes())if(x.id!==n.id)for(const o of ports(x).outputs)if(o.type!=='VOID'&&compatible(o.type,p.type))options.push({value:x.id+'::'+o.name,label:nodeTitle(x)+' · '+x.id+'.'+(o.label||o.name)});const fallback=`<input data-inspectparam="${esc(p.name)}" value="${esc(n.params?.[p.name]??p.default??'0')}">`;return `<div class="field"><span>${esc(p.label||p.name)} <small>${esc(p.type)}</small></span>${e?`<span class="field-link">${esc(e.from+'.'+e.out)}<button data-unlink="${esc(e.id)}" type="button">×</button></span>`:p.type.startsWith('VAR:')?'<span class="linked">Ref 연결 필요</span>':parameterControl(n,p,n.params?.[p.name]??p.default??'0',n.id+'::param::'+p.name,resolve,fallback)}<select data-bind="${esc(p.name)}" aria-label="${esc(p.name+' 데이터 연결')}"><option value="">${e?'데이터 연결 변경…':'값 선택 / 데이터 노드 연결…'}</option>${options.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</select></div>`}

function evidence(n){const item=exported.get(n.api);if(!item)return '';const walk=(rva,depth,seen)=>{if(depth>1||seen.has(rva))return '';const rows=C.calls[rva]||[];seen=new Set([...seen,rva]);return rows.slice(0,12).map(c=>`<div class="static-call">${c.target?`<a href="../control-panel.html?rva=${c.target}" target="_blank" rel="noopener">${esc(c.name)}</a>`:esc(c.name)}<small>${esc(c.site||'')} · ${c.kind==='indirect'?'간접 대상 미확정':'직접 call 후보'} ${c.target||''}</small>${c.kind==='direct'?walk(c.target,depth+1,seen):''}</div>`).join('')};return `<h3>바이너리 내부 호출 근거</h3><div class="note">이 버전의 직접 call 명령을 해석한 정적 후보입니다. 실행된 분기나 실제 런타임 호출 스택을 의미하지 않습니다. 간접 호출과 tail jump는 완전하게 추적하지 않습니다.</div><div class="evidence">${walk(item.rva,0,new Set())||'<span class="muted">확인된 직접 call이 없습니다. leaf 함수 또는 tail transfer일 수 있습니다.</span>'}</div>${item.report?`<p><a href="../${esc(item.report)}" target="_blank" rel="noopener">어셈블리 / 분석 보고서 열기 ↗</a></p>`:''}`}
function wireInspector(n){if(n?.api==='DbgPrint'&&$('printStyle'))wirePrintInspector(n);if($('runRegression'))$('runRegression').onclick=runBrowserRegression;if($('saveRegression'))$('saveRegression').onclick=()=>download('kernel-browser-regression.json',regressionReport);document.querySelectorAll('[data-setting]').forEach(el=>el.oninput=()=>{let val=el.type==='checkbox'?el.checked:el.value;const key=el.dataset.setting;if(['memoryMB','userMemoryMB','seed','stepMs','maxSteps'].includes(key)){val=Number(val);const ranges={memoryMB:[1,128],userMemoryMB:[4,128],seed:[0,4294967295],stepMs:[50,2000],maxSteps:[100,100000]};const [min,max]=ranges[key];if(!Number.isFinite(val)||val<min||val>max){toast(`설정 범위: ${min}–${max}`);return}}settings[key]=val;persist();controls();toast('새 실행부터 적용됩니다.')});wireFunctionInspector();if(n&&VARIABLE_KINDS.includes(n.kind))wireVariableInspector(n);if($('openSettings'))$('openSettings').onclick=()=>setInspector('settings');if($('deleteEdge'))$('deleteEdge').onclick=()=>commit(()=>{program.edges=program.edges.filter(e=>e.id!==selectedEdge);selectedEdge=null});bindLoopControls($('inspectorBody'),program,commit);wireBranchControls($('inspectorBody'));bindConstantControls($('inspectorBody'),program,commit,resolve);if(!n)return;wireDefinitionInspector(n);const peek=$('peekMemory');if(peek)peek.onclick=()=>{try{const p=engine?.world.byNode.get(n.id),address=literal($('peekAddress').value);$('peekResult').textContent=peekUser(p,address)}catch(error){$('peekResult').textContent=error.message}};document.querySelectorAll('[data-nodefield]').forEach(el=>el.oninput=()=>{const value=el.value,key=el.dataset.nodefield;edit(()=>n[key]=['size','width'].includes(key)?Number(value):value)});document.querySelectorAll('[data-structfield]').forEach(el=>el.oninput=()=>edit(()=>{n.values??={};n.values[el.dataset.structfield]=el.value}));document.querySelectorAll('[data-inspectparam]').forEach(el=>el.oninput=()=>{if(n.kind==='structField'&&el.dataset.inspectparam==='Field')commit(()=>{n.params.Field=el.value;reconcileVariablePins(program,enginePorts,compatible)});else edit(()=>{n.params??={};n.params[el.dataset.inspectparam]=el.value})});document.querySelectorAll('[data-unlink]').forEach(el=>el.onclick=e=>{e.preventDefault();commit(()=>program.edges=program.edges.filter(x=>x.id!==el.dataset.unlink))});document.querySelectorAll('[data-bind]').forEach(el=>el.onchange=()=>{if(!el.value)return;const [id,port]=el.value.split('::'),source=ports(program.nodes.find(x=>x.id===id)).outputs.find(x=>x.name===port),target=ports(n).inputs.find(x=>x.name===el.dataset.bind);completeConnection({id,dir:'out',name:port,type:source.type},{id:n.id,dir:'in',name:target.name,type:target.type})});document.querySelectorAll('[data-exec]').forEach(el=>el.onchange=()=>commit(()=>{program.edges=program.edges.filter(e=>!(e.kind==='exec'&&e.from===n.id&&e.out===el.dataset.exec));if(el.value){const [to,input='exec']=el.value.split('::');program.edges.push({id:unique('edge'),kind:'exec',from:n.id,out:el.dataset.exec,to,in:input});}}));if($('toggleBreakpoint'))$('toggleBreakpoint').onclick=()=>commit(()=>n.breakpoint=!n.breakpoint);if($('deleteNode'))$('deleteNode').onclick=deleteSelection;if($('duplicate'))$('duplicate').onclick=()=>{const copy=structuredClone(n);copy.id=unique(n.kind);copy.x+=65;copy.y+=70;copy.breakpoint=false;commit(()=>program.nodes.push(copy));selected=copy.id;renderGraph();renderInspector()};if($('focusNode'))$('focusNode').onclick=()=>focusNode(n.id,true);}
function deleteSelection(){if(internalView?.active)return;if(selected){const n=program.nodes.find(n=>n.id===selected);if(['entry','functionEntry'].includes(n?.kind)){toast('그래프의 진입점은 삭제할 수 없습니다.');return}commit(()=>{program.nodes=program.nodes.filter(n=>n.id!==selected);program.edges=program.edges.filter(e=>e.from!==selected&&e.to!==selected);selected=null})}else if(selectedEdge)commit(()=>{program.edges=program.edges.filter(e=>e.id!==selectedEdge);selectedEdge=null})}
function controls(){const state=engine?.state||'idle',running=state==='running';$('run').disabled=running||!!stepper?.busy||lockRevision>=revision;$('run').textContent=state==='paused'&&startedRevision===revision?'▶ 계속 실행':lockRevision>=revision?'수정 후 실행 가능':'▶ 시뮬레이션 시작';$('pause').disabled=!running&&!stepper?.busy;$('step').disabled=running||!!stepper?.busy||lockRevision>=revision||['crashed','unsupported'].includes(state)&&startedRevision===revision;$('stepOver').disabled=$('step').disabled;$('stepOut').disabled=$('step').disabled||!stepper?.canOut();$('stop').disabled=!engine||['stopped','completed','crashed','unsupported'].includes(state);$('undo').disabled=!undo.length;$('redo').disabled=!redo.length;$('runState').textContent=state==='unsupported'&&engine.error?.diagnostic==='BOUNDS_ERROR'?'BOUNDS ERROR':state.toUpperCase();$('validationInfo').textContent=lockRevision>=revision?'문제 노드의 인자 / 연결을 수정하세요.':engine?.error&&startedRevision===revision?(engine.error.diagnostic||engine.error.status):'EXPORT API · '+available.length+'개 실행 모델';document.body.classList.toggle('crashed',state==='crashed')}
function createEngine(){stepper?.cancel();internalView?.close();engine?.stop();engine=new Engine(program,C,{...settings,driverName:$('projectName').value,speed:Number($('speed').value)},runtimeChanged);const errors=engine.validate();if(errors.length){engine=null;toast('실행 전 확인\n'+errors.slice(0,8).join('\n'));return false}stepper=new DebugStepper(engine,runtimeChanged);startedRevision=revision;memSelection=null;return true;}
function start(){try{if(stepper?.busy)return;if(engine?.state==='paused'&&startedRevision===revision){engine.run();controls();return}if(!createEngine())return;engine.run();setInspector('runtime');controls()}catch(error){toast(error.message);if(engine){engine.state='unsupported';engine.error={reason:error.message,status:'STATUS_NOT_IMPLEMENTED'};}controls()}}
async function debugStep(mode='into'){
 try{
  if(stepper?.busy)return;
  if(!engine||!['paused','running'].includes(engine.state)||startedRevision!==revision){if(!createEngine())return;engine.start();engine.pause();runtimeChanged(engine);return;}
  const activeEngine=engine,controller=stepper;await controller.command(mode);if(engine!==activeEngine||stepper!==controller||controller.reason==='cancelled')return;
  if(mode==='into'&&engine.stage&&!['crashed','unsupported'].includes(engine.state)){graphGesture.end(null,'internal');hideArgumentTip();internalView.open(engine);setInspector('runtime');}
  else internalView.sync(engine);
  if(engine.current&&!internalView.active){const n=engine.node(engine.current);if(n&&graphOf(n)!==graphView)switchGraph(graphOf(n),{nodeId:n.id,runtime:true});focusNode(engine.current,true)}
  if(stepper.reason==='waiting')toast('신호 / 이벤트 대기 상태입니다. 계속 실행하거나 일시정지 상태에서 다시 진행하세요.');
  if(stepper.reason==='step-limit')toast('디버그 명령의 진행 한도에서 멈췄습니다.');
  runtimeChanged(engine);
 }catch(error){toast(error.message)}
}
function oneStep(){return debugStep('into')}

function runtimeChanged(e){e.variables.refresh();internalView?.sync(e);if(e.state!=='paused')hideArgumentTip();else if(pinnedArgument&&argumentAnchor){const a=argumentAnchor;showArgumentTip(a.label,a.x,a.y,true)}controls();const transfer=e.functions.transfer;if($('functionFlow'))$('functionFlow').textContent=transfer?(transfer.kind==='call'?'→ 호출 · ':'↩ 복귀 · ')+nodeTitle(program.nodes.find(n=>n.id===transfer.from))+' → '+nodeTitle(program.nodes.find(n=>n.id===transfer.to)):'인자 / 반환 핀으로 함수 재사용';$('clock').textContent=clock(e.time);$('irql').textContent='IRQL '+e.irql+' · '+['PASSIVE','APC','DISPATCH'][e.irql];$('stackCount').textContent=e.stack.length;$('poolCount').textContent=e.mem.blocks.filter(b=>b.kind==='pool'&&!b.freed).length;highlight();if(e.current&&e.current!==runtimeChanged.lastNode&&(settings.follow||stepper?.busy)){const n=program.nodes.find(n=>n.id===e.current);if(n&&graphOf(n)!==graphView)switchGraph(graphOf(n),{nodeId:n.id,runtime:true});const r=$('canvas').getBoundingClientRect();if(n){const x=n.x*camera.z+camera.x,y=n.y*camera.z+camera.y;if(x<0||x+268*camera.z>r.width||y<0||y+220*camera.z>r.height)focusNode(n.id)}}runtimeChanged.lastNode=e.current;if(performance.now()-lastPaint>90||e.state!=='running'){lastPaint=performance.now();renderDebugger();renderProcessViews();if(inspector==='runtime')renderInspector()}if(e.state==='crashed'&&!e.shownCrash){e.shownCrash=true;lockRevision=revision;showCrash(e.error);controls()}if(e.state==='unsupported'&&!e.shownGap){e.shownGap=true;selected=e.error?.node;focusNode(selected,true);setInspector('node');highlight();toast('실행 모델 중단 · '+e.error.reason)}}
function clock(ms){const m=Math.floor(ms/60000),s=Math.floor(ms/1000)%60,milli=Math.floor(ms%1000);return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'.'+String(milli).padStart(3,'0')}
function renderDebugger(){const outputEl=$('debugBody').querySelector('.debug-output-log'),outputScroll=outputEl?.scrollTop||0,outputFollow=!outputEl||outputEl.scrollHeight-outputEl.clientHeight-outputEl.scrollTop<24;const variableScroll=debug==='variables'?[...document.querySelectorAll('.variable-watch-pane')].map(el=>el.scrollTop):[];let html='';if(!engine&&debug==='output'){$('debugBody').innerHTML=outputView({debugOutput:[]},clock,esc);return}if(!engine){$('debugBody').innerHTML='<div class="debug-empty"><span class="symbol">⌁</span><span>가상 드라이버가 준비되었습니다.<br><b>시뮬레이션 시작</b>을 누르면 콜 스택, 가상 메모리와 타이머가 실시간으로 표시됩니다.</span></div>';return}if(debug==='stack'){const stack=[...engine.stack].reverse();html=stack.length?'<table class="debug-table"><thead><tr><th>#</th><th>SYMBOL / MODEL STEP</th><th>ORIGIN</th><th>CONTEXT</th></tr></thead><tbody>'+stack.map((f,i)=>`<tr ${f.functionId?'data-open-fngraph="'+esc(f.functionId)+'"':''}><td class="dim">${String(i).padStart(2,'0')}</td><td class="${f.origin}">${esc(f.name)}</td><td class="dim">${f.origin==='model'?'계약 모델 단계':f.origin==='export'?'현재 이미지 EXPORT':f.origin==='user'?'사용자 함수':'가상 드라이버'}</td><td class="dim">${esc(f.detail)}</td></tr>`).join('')+'</tbody></table>':'<div class="debug-empty"><span class="symbol">⌁</span><span>호출 스택이 비어 있습니다. '+(engine.queue.length?'타이머 또는 DPC 이벤트를 기다리고 있습니다.':'드라이버 루틴이 반환했습니다.')+'</span></div>';if(engine.wait)html+='<div class="note">THREAD WAIT · '+(Number.isFinite(engine.wait.waitUntil)?Math.max(0,engine.wait.waitUntil-engine.time).toFixed(0)+'ms':'신호 대기')+'</div>'}
else if(debug==='output'){html=outputView(engine,clock,esc)}
else if(debug==='memory'){const blocks=engine.mem.blocks.slice(-200).reverse(),chosen=blocks.find(b=>b.id===memSelection)||blocks.find(b=>!b.freed);html='<div class="memory-split"><div><table class="debug-table"><thead><tr><th>ADDRESS</th><th>BYTES</th><th>TAG / TYPE</th><th>STATE</th></tr></thead><tbody>'+blocks.map(b=>`<tr data-block="${b.id}" style="cursor:pointer"><td class="${b.freed?'dim':'export'}">${hex(b.address)}</td><td>${b.size.toLocaleString()}</td><td>${esc(b.tag)} <small>${b.pool}</small></td><td style="color:${b.freed?'#8e7b83':'#7be0bc'}">${b.freed?'FREED':b.kind.toUpperCase()}</td></tr>`).join('')+'</tbody></table></div><div class="hexview">'+(chosen?esc(memoryDump(chosen)):'No allocations')+'</div></div>'}
else if(debug==='events'){html='<table class="debug-table"><thead><tr><th>VIRTUAL TIME</th><th>EVENT</th><th>DETAIL</th></tr></thead><tbody>'+engine.events.slice(-180).reverse().map(e=>`<tr data-eventnode="${esc(e.node||'')}"><td class="dim">${clock(e.time)}</td><td style="color:${e.kind==='crash'?'#ff8792':e.kind==='hardware'?'#b9a3ec':'#7be0bc'}">${esc(e.kind.toUpperCase())}</td><td>${esc(e.message)}</td></tr>`).join('')+'</tbody></table>'}
else if(debug==='variables'){html=variablesDebugger(engine,fmt,hex,variableDebugState)}else if(debug==='functions'){html=functionHistory(engine,fmt)}else if(debug==='loops'){html=loopDebugger(engine)}else if(['registers','processes','callbacks'].includes(debug)){html=processDebug(debug)}else{const h=engine.hardware;html='<div class="hardware-grid">'+[['VIRTUAL BAR0',hex(h.base)],['DOORBELL',hex(h.doorbell>>>0,8)],['STATUS',h.status?'COMPLETE':'IDLE / BUSY'],['VIRTUAL IRQ',h.interrupts]].map(([label,value])=>`<div class="hw-card"><small>${label}</small><b>${esc(value)}</b></div>`).join('')+'</div><div style="padding:0 17px;color:#879db5;font-size:10px">교육용 주변 장치 모델 · '+h.mappings.length+' MMIO mapping(s) · Doorbell 기록 후 가상 250ms 지연</div>'}
$('debugBody').innerHTML=html;if(debug==='output'){const log=$('debugBody').querySelector('.debug-output-log');if(log)log.scrollTop=outputFollow?log.scrollHeight:outputScroll;}if(debug==='variables'){if($('expandVariableWatch'))$('expandVariableWatch').onclick=()=>{document.body.classList.toggle('variables-expanded');requestAnimationFrame(drawWires)};document.querySelectorAll('.variable-watch-pane').forEach((el,i)=>el.scrollTop=variableScroll[i]||0);document.querySelectorAll('[data-expand-variable]').forEach(el=>el.ontoggle=()=>{const id=Number(el.dataset.expandVariable);if(el.open)variableDebugState.expanded.add(id);else variableDebugState.expanded.delete(id)});document.querySelectorAll('[data-aggregate-page]').forEach(el=>el.onclick=()=>{const [id,page]=el.dataset.aggregatePage.split(':').map(Number);variableDebugState.pages.set(id,page);variableDebugState.expanded.add(id);renderDebugger()});}wireFunctionLinks($('debugBody'));document.querySelectorAll('[data-block]').forEach(el=>el.onclick=()=>{memSelection=Number(el.dataset.block);renderDebugger()});document.querySelectorAll('[data-eventnode]').forEach(el=>el.onclick=()=>{if(!el.dataset.eventnode)return;selected=el.dataset.eventnode;focusNode(selected,true);setInspector('node');highlight()});}
function memoryDump(b){const d=engine.mem.bytes.slice(b.start,b.start+Math.min(b.size,128));let out=hex(b.address)+'  '+b.tag+'\n\n';for(let i=0;i<d.length;i+=16){const line=d.slice(i,i+16);out+=i.toString(16).padStart(4,'0')+'  '+[...line].map(x=>x.toString(16).padStart(2,'0')).join(' ')+'\n'}const obj=engine.mem.objects.get(hex(b.address));if(obj)out+='\n'+obj.type+'\n'+JSON.stringify(obj.fields,(_,v)=>typeof v==='bigint'?hex(v):v,2);return out}
function showCrash(err){$('crashName').textContent=err.bugcheck;$('crashReason').textContent=err.reason;$('crashStatus').textContent=err.status+' ('+hex(STATUS[err.status]??0,8)+')';$('crashBug').textContent=hex(err.code,8)+' · '+err.params.map(String).join(', ');$('crashNode').textContent=err.node+' · '+nodeTitle(program.nodes.find(n=>n.id===err.node));$('crashDialog').showModal()}
function download(name,obj){const blob=new Blob([JSON.stringify(obj,(_,v)=>typeof v==='bigint'?hex(v):v,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function loadExample(){const next=template($('example').value);commit(()=>{graphView='main';program=next;selected=program.nodes[0].id;selectedEdge=null});engine?.stop();engine=null;lockRevision=-1;setInspector('node');renderDebugger();controls();requestAnimationFrame(()=>{camera={x:40,y:18,z:.68};const r=$('canvas').getBoundingClientRect();camera.x=r.width/2-550*.68;transform();drawWires()});toast('예제 열기 · '+$('example').selectedOptions[0].textContent)}

function processView(n){const p=engine?.world.byNode.get(n.id);if(!p)return '<div class="proc-state">○ 생성 대기 · Run 타이머 또는 자동 시작</div>';const rows=p.vm.regions();return `<div class="proc-state"><i style="background:${p.alive?'#7be0bc':'#fa7184'}"></i>${p.alive?(p.pending?'생성 콜백 처리 중':'RUNNING'):'EXITED'} · PID ${p.pid}</div><div class="proc-handle">Handle ${hex(p.handle)}<br>EPROCESS ${hex(p.pointer)}</div><div class="vm-strip">${rows.map(r=>`<span style="background:${r.state==='COMMITTED'?'#527fac':'#53616c'};flex:${Math.max(1,Math.log2(Number(r.size)))}" title="${hex(r.base)} + ${r.size}"></span>`).join('')}</div><div class="proc-regions">${rows.slice(0,8).map(r=>`<div><b>${hex(r.base)}</b><span>${Number(r.size/1024n)}K</span><small>${r.state==='COMMITTED'?'COMMIT':'RESERVE'} / ${hex(r.protect)}</small></div>`).join('')||'<span>유저 VA 매핑 없음</span>'}</div>`;}
function renderProcessViews(){document.querySelectorAll('[data-processview]').forEach(el=>{const n=program.nodes.find(n=>n.id===el.dataset.processview);if(n){const html=processView(n);if(el.innerHTML!==html){el.innerHTML=html;requestAnimationFrame(drawWires)}}});const live=$('processInspectorLive');if(live){const n=program.nodes.find(n=>n.id===selected);if(n)live.innerHTML=processView(n);}}
function processInspector(n){if(n.kind==='process')return field('프로그램 이름',n.name,'data-nodefield="name"')+field('PID (0 = 자동)',n.pid||'0','data-nodefield="pid"')+field('가상 이미지 경로',n.image,'data-nodefield="image"')+'<div class="note">실행 입력이 연결되면 해당 흐름에서 생성합니다. 입력이 없으면 시작 시 존재하는 프로세스로 만듭니다. Handle은 드라이버용 커널 핸들입니다. 프로세스 이미지 코드는 실제로 실행하지 않습니다.</div><div id="processInspectorLive">'+processView(n)+'</div><h3>디버거의 유저 VA 보기</h3><input id="peekAddress" value="0x10000000" aria-label="유저 VA 검사 주소" style="width:100%"><button id="peekMemory" style="margin-top:6px">64바이트 보기</button><pre id="peekResult" class="peek-result"></pre>';if(n.kind==='runTimer')return field('시작 후 지연 (ms)',n.delayMs,'data-nodefield="delayMs" type="number" min="0" max="86400000"')+'<p>1000ms = 1초입니다. 실행 큐가 바쁘면 실행 시각은 지연될 수 있으며 로그에 만료 시각과 실행 시각을 구분합니다.</p>';if(n.kind==='handler'){const h=HANDLERS[n.handlerType];return '<div class="note">'+esc(h?.title)+' 전용 서명입니다. Routine을 호환되는 등록 API에 연결하고, 아래 실행 핀으로 핸들러 본문을 작성하세요. '+(h?.returns==='VOID'?'이 핸들러의 반환 상태는 통지 결과에 사용하지 않습니다.':'Return NTSTATUS로 pre-notification 허용/차단 상태를 반환합니다.')+'</div><p>실제 인자: '+esc((h?.args||[]).slice(0,n.handlerType==='processEx'?3:n.handlerType==='image'?3:n.handlerType==='registry'?3:99).map(([name,type])=>type+' '+name).join(', '))+'</p>'+(n.handlerType==='processEx'?'<p>CreationStatusSlot, ImageFileName은 모델의 명시적 보조 출력입니다. 비공개 필드 오프셋을 가정하지 않습니다.</p>':'');}return `<label class="field">유저 이벤트<select data-nodefield="eventType">${[['registry','레지스트리 값 설정 (PreSetValueKey)'],['thread','스레드 생성'],['threadExit','스레드 종료'],['image','이미지 로드 통지'],['write','유저 메모리 쓰기'],['exit','프로세스 종료']].map(([v,label])=>`<option value="${v}" ${n.eventType===v?'selected':''}>${label}</option>`).join('')}</select></label>${field('키 / 이미지 이름',n.text||'','data-nodefield="text"')}${field('레지스트리 값',n.eventValue||'Demo','data-nodefield="eventValue"')}${field('스레드 ID',n.threadId||'5000','data-nodefield="threadId"')}<p>시나리오의 유저 동작을 생성하는 노드입니다. 커널 API 노드와 구분됩니다.</p>`;}
function peekUser(p,address){if(!p?.alive)return '프로세스가 실행 중이 아닙니다.';let out='PID '+p.pid+' @ '+hex(address)+'\n';for(let row=0;row<4;row++){const bytes=[];for(let i=0;i<16;i++){const addr=address+BigInt(row*16+i),page=p.vm.pages.get(addr&~4095n);bytes.push(page?page.bytes[Number(addr&4095n)].toString(16).padStart(2,'0'):'??')}out+=hex(address+BigInt(row*16))+'  '+bytes.join(' ')+'\n'}return out;}
function processDebug(tab){const w=engine.world;if(tab==='registers')return '<div class="register-context">스레드 소유 PID '+w.ownerPid+' · 현재 주소 공간 PID '+w.currentPid+' · attach '+w.attach.length+' · '+(w.normalApcDisabled||engine.irql>=1?'normal APC disabled':'normal APC enabled')+' · x64 ABI 표시 모델</div><div class="register-bank">'+Object.entries(w.registers).filter(([k])=>k!=='stackArgs').map(([k,v])=>'<div><small>'+k+'</small><b>'+hex(v,16)+'</b></div>').join('')+'</div><div class="register-context">Stack arguments: '+esc(w.registers.stackArgs.map(fmt).join(', '))+'</div>';if(tab==='callbacks')return '<table class="debug-table"><thead><tr><th>COOKIE</th><th>SIGNATURE</th><th>HANDLER</th><th>STATE</th><th>CALL COUNT</th></tr></thead><tbody>'+w.registrations.map(r=>'<tr><td>'+hex(r.cookie)+'</td><td>'+esc(r.type)+'</td><td>'+esc(r.handler)+'</td><td>'+(r.active?'REGISTERED':'REMOVED')+'</td><td>'+w.callbackHistory.filter(h=>h.node===r.handler).length+'</td></tr>').join('')+'</tbody></table>';return '<table class="debug-table"><thead><tr><th>PID / PROCESS</th><th>HANDLE</th><th>USER COMMIT</th><th>STATE</th></tr></thead><tbody>'+[...w.processes.values()].map(p=>'<tr><td>'+p.pid+' / '+esc(p.name)+'</td><td>'+hex(p.handle)+'</td><td>'+(p.vm.committed/1024).toFixed(0)+' KB</td><td>'+(p.alive?'RUNNING':'EXITED')+'</td></tr>').join('')+'</tbody></table>';}


function validationInspector(){return '<div class="eyebrow">EXPECTED / OBSERVED</div><h2>시나리오 회귀 검증</h2><p>제공하는 예제 전체와 주소 공간 / 콜백 실패 경로를 7·33·660ms의 시계 분할로 검증합니다. 실제 Windows 실행과의 대조 인증은 아닙니다.</p><button id="runRegression" class="run" '+(verifying?'disabled':'')+'>'+(verifying?'검증 중…':'내장 시나리오 검증 실행')+'</button>'+(regressionReport?'<div class="note '+(regressionReport.failed?'warning':'')+'">'+regressionReport.passed+' / '+regressionReport.total+' PASS · '+regressionReport.failed+' FAIL</div><button id="saveRegression">결과 JSON 저장</button>'+regressionReport.rows.map(r=>'<div class="regression-row '+(r.pass?'pass':'fail')+'"><b>'+(r.pass?'PASS':'FAIL')+'</b> '+esc(r.name)+'<small>예상: '+esc(r.expected)+'<br>관측: '+esc(r.actual)+'</small></div>').join(''):'<div class="note">가상 메모리, DriverEntry, IRQL, 타이머/DPC, 가상 MMIO, 프로세스 VA, 통지 콜백, 오류 중단, 정상 NTSTATUS 실패를 포함합니다.</div>');}
async function runBrowserRegression(){if(verifying)return;engine?.pause();verifying=true;const previousSerial=serial;regressionReport={total:0,passed:0,failed:0,rows:[]};renderInspector();try{regressionReport=await runScenarios(template,C,(rows,done,total)=>{regressionReport={total,passed:rows.filter(r=>r.pass).length,failed:rows.filter(r=>!r.pass).length,rows};if(inspector==='validation')renderInspector()});}catch(error){toast(error.message)}finally{serial=previousSerial;verifying=false;renderInspector();toast('회귀 검증 '+regressionReport.passed+'/'+regressionReport.total+' 통과')}}

function init(){try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.schema===1){program=cleanProgram(saved.program);settings={...settings,...saved.settings};settings.memoryMB=[1,4,8,16,32,64,128].includes(Number(settings.memoryMB))?Number(settings.memoryMB):16;settings.userMemoryMB=[4,16,32,64,128].includes(Number(settings.userMemoryMB))?Number(settings.userMemoryMB):64;settings.speed=1;graphView=typeof saved.graphView==='string'?saved.graphView:'main';graphCameras=saved.graphCameras&&typeof saved.graphCameras==='object'?saved.graphCameras:{};settings.stepMs=Math.max(50,Math.min(2000,Number(settings.stepMs)||240));settings.maxSteps=Math.max(100,Math.min(100000,Number(settings.maxSteps)||10000));serial=Number(saved.serial)||1000;if(saved.camera&&[saved.camera.x,saved.camera.y,saved.camera.z].every(Number.isFinite))camera=saved.camera;$('projectName').value=String(saved.name||'NodeDriver').slice(0,80)}}catch{}program??=template('pool');serial=Math.max(serial,1000);selected=program.nodes.find(n=>n.kind==='entry')?.id;$('imageInfo').textContent=C.architecture+' · '+C.sha256.slice(0,12)+' · PDB '+String(C.pdb.symbol_key||'').slice(0,12);$('sources').innerHTML='<div class="eyebrow">MODEL CONTRACT SOURCES</div>'+[['DriverEntry','https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/wdm/nc-wdm-driver_initialize'],['ExAllocatePool2','https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/wdm/nf-wdm-exallocatepool2'],['ExFreePoolWithTag','https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/wdm/nf-wdm-exfreepoolwithtag'],['KeSetTimer / DPC','https://learn.microsoft.com/en-us/windows-hardware/drivers/ddi/wdm/nf-wdm-kesettimer'],['BAD_POOL_CALLER','https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-0xc2--bad-pool-caller'],['NTSTATUS','https://learn.microsoft.com/en-us/windows-hardware/drivers/kernel/using-ntstatus-values']].map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener">Microsoft Learn · ${label} ↗</a>`).join('');renderPalette();renderGraph();renderInspector();renderDebugger();controls();if(!localStorage.getItem(KEY))requestAnimationFrame(()=>{const r=$('canvas').getBoundingClientRect();camera.x=r.width/2-550*camera.z;transform();drawWires()});}
