function zoom(factor,cx,cy){const r=$('canvas').getBoundingClientRect(),x=cx??r.width/2,y=cy??r.height/2,z=Math.min(1.8,Math.max(.22,camera.z*factor));camera.x=x-(x-camera.x)*z/camera.z;camera.y=y-(y-camera.y)*z/camera.z;camera.z=z;transform();drawWires();persist()}
