let suppressGestureClick=false;
const graphGesture=createGraphGesture($('canvas'),{
 active:on=>$('canvas').classList.toggle('graph-dragging',on),
 move(d,dx,dy){
  if(d.type==='node'){
   d.n.x=d.x+dx/camera.z;d.n.y=d.y+dy/camera.z;
   const el=document.getElementById('node-'+d.n.id);
   if(el){el.style.left=d.n.x+'px';el.style.top=d.n.y+'px';drawWires()}
  }else if(d.type==='pan'){camera.x=d.x+dx;camera.y=d.y+dy;transform()}
  else if(d.type==='pin'&&d.moved){connect=d.pin;showConnect()}
 },
 finish(d,e,reason){
  suppressGestureClick=d.moved||d.type==='pin';
  if(d.type==='node'&&reason!=='render'&&snapshot()!==d.before){undo.push(d.before);redo=[];persist();controls()}
  if(d.type==='pan'){drawWires();persist()}
  if(d.type==='pin'){
   if(reason!=='release'){connect=null;showConnect();return}
   if(!d.moved){selectPin(d.pin);return}
   const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-pin]');
   connect=null;showConnect();
   // Dropping a dragged wire on empty space cancels it; click-to-click wiring
   // remains available through a stationary pin click.
   if(target){completeConnection(d.pin,pinInfo(target));connect=null;showConnect()}
  }
 }
});
$('canvas').addEventListener('pointerdown',()=>{suppressGestureClick=false},true);
$('canvas').addEventListener('click',e=>{if(suppressGestureClick){suppressGestureClick=false;e.preventDefault();e.stopImmediatePropagation()}},true);
$('canvas').addEventListener('selectstart',e=>{if(!e.target.closest?.('input,textarea,[contenteditable="true"]'))e.preventDefault()});
$('canvas').addEventListener('dragstart',e=>e.preventDefault());
$('canvas').onwheel=e=>{if(e.target.closest('input,textarea,select'))return;e.preventDefault();if(graphGesture.current)return;const r=$('canvas').getBoundingClientRect();zoom(e.deltaY<0?1.08:.925,e.clientX-r.left,e.clientY-r.top)};
$('canvas').addEventListener('pointerdown',e=>{
 if(e.target.closest('input,textarea,button,select,[contenteditable="true"],[data-pin]')||e.button!==0||e.isPrimary===false)return;
 const header=e.target.closest('[data-drag]');
 if(header){
  const n=program.nodes.find(n=>n.id===header.dataset.drag);if(!n)return;
  if(!graphGesture.begin(e,{type:'node',n,x:n.x,y:n.y,before:snapshot()}))return;
  selected=n.id;selectedEdge=null;highlight();setInspector('node')
 }else if(!e.target.closest('.node,[data-wire],#miniMap,.zoom-tools')){
  if(!graphGesture.begin(e,{type:'pan',x:camera.x,y:camera.y}))return;
  selected=null;selectedEdge=null;highlight()
 }
});
