function reconcilePrintEdges(n){const ps=new Map(ports(n).inputs.map(p=>[p.name,p]));program.edges=program.edges.filter(e=>{if(e.kind!=='data'||e.to!==n.id)return true;const source=program.nodes.find(n=>n.id===e.from),out=source&&ports(source).outputs.find(p=>p.name===e.out);return ps.has(e.in)&&out&&compatible(out.type,ps.get(e.in).type)});}
