 graphGesture.end(null,'context');closeNodeMenu();hideArgumentTip();selected=id;selectedEdge=null;highlight();setInspector('node');
 const n=program.nodes.find(n=>n.id===id),protectedEntry=['entry','functionEntry'].includes(n.kind);
